<!DOCTYPE html>
<html lang="fr">
<head>
    <meta charset="utf-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title>Créer un compte — Niscavor Stock</title>
    <link href="https://fonts.googleapis.com/css2?family=Syne:wght@700;800&family=DM+Sans:wght@400;500;600&display=swap" rel="stylesheet">
    @vite(['resources/css/app.css', 'resources/js/app.js'])
    <link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.2/dist/css/bootstrap.min.css" rel="stylesheet">
    <link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css">
    <style>
        :root{--navy:#0d1b2a;--navy2:#1b2a3d;--gold:#f0a500;--gold2:#ffc642;--red:#e63946;}
        *{box-sizing:border-box;}
        body{
            min-height:100vh;font-family:'DM Sans',sans-serif;
            background:linear-gradient(145deg,#0d1b2a 0%,#1b2a3d 50%,#0f3460 100%);
            display:flex;align-items:center;justify-content:center;padding:1rem;
        }

        /* ── CARD ── */
        .reg-card{
            background:rgba(255,255,255,.05);
            backdrop-filter:blur(24px);-webkit-backdrop-filter:blur(24px);
            border:1px solid rgba(240,165,0,.2);
            border-radius:24px;padding:2.5rem 2rem;
            width:100%;max-width:430px;
            box-shadow:0 30px 70px rgba(0,0,0,.4);
            animation:slideUp .5s ease;
        }
        @keyframes slideUp{from{transform:translateY(20px);opacity:0;}to{transform:translateY(0);opacity:1;}}

        /* ── BRAND ── */
        .brand{text-align:center;margin-bottom:2rem;}
        .brand img{display:block;margin:0 auto;
            width:78px;height:78px;border-radius:20px;object-fit:cover;
            border:3px solid var(--gold);
            box-shadow:0 8px 28px rgba(240,165,0,.35);
            margin-bottom:1rem;
        }
        .brand h1{font-family:'Syne',sans-serif;font-weight:800;color:#fff;font-size:1.5rem;margin:0;}
        .brand p{color:var(--gold);font-size:.7rem;letter-spacing:3px;text-transform:uppercase;margin:.25rem 0 0;}

        /* ── FIELDS ── */
        .f-label{color:rgba(255,255,255,.7);font-size:.8rem;font-weight:600;margin-bottom:.4rem;display:block;}
        .f-input{
            background:rgba(255,255,255,.08);border:1.5px solid rgba(255,255,255,.12);
            border-radius:10px;color:#fff;padding:.65rem 1rem;font-size:.9rem;
            width:100%;transition:.25s;
        }
        .f-input:focus{
            background:rgba(255,255,255,.13);border-color:var(--gold);
            box-shadow:0 0 0 3px rgba(240,165,0,.18);outline:none;color:#fff;
        }
        .f-input::placeholder{color:rgba(255,255,255,.3);}
        .f-group{margin-bottom:1.1rem;}
        .f-icon{position:relative;}
        .f-icon i{position:absolute;left:.9rem;top:50%;transform:translateY(-50%);
                   color:rgba(255,255,255,.35);font-size:.9rem;pointer-events:none;}
        .f-icon .f-input{padding-left:2.4rem;}

        /* ── ERROR ── */
        .err{color:#ff7b82;font-size:.76rem;margin-top:.3rem;display:flex;align-items:center;gap:.3rem;}

        /* ── DIVIDER ── */
        .divider{border-top:1px solid rgba(255,255,255,.1);margin:1.5rem 0;}

        /* ── SUBMIT ── */
        .btn-reg{
            background:linear-gradient(135deg,var(--gold),var(--gold2));
            border:none;border-radius:12px;color:var(--navy);
            font-family:'Syne',sans-serif;font-weight:800;font-size:1rem;
            padding:.8rem;width:100%;transition:.25s;letter-spacing:.3px;
        }
        .btn-reg:hover{transform:translateY(-2px);box-shadow:0 8px 22px rgba(240,165,0,.4);color:var(--navy);}

        /* ── LINK ── */
        .link-login{color:rgba(255,255,255,.5);font-size:.875rem;text-decoration:none;transition:.2s;}
        .link-login:hover{color:var(--gold);text-decoration:underline;}
        .link-login strong{color:rgba(255,255,255,.75);}

        /* ── RESPONSIVE ── */
        @media(max-width:480px){
            .reg-card{padding:1.8rem 1.4rem;border-radius:20px;}
            .brand img{display:block;margin:0 auto;width:62px;height:62px;}
            .brand h1{font-size:1.25rem;}
        }
    </style>
</head>
